import React, { useState } from 'react';
import { motion } from 'framer-motion';
import { useOSStore } from '../store/useOSStore';
import {
  Smartphone,
  Tablet,
  MessageSquare,
  UserCheck,
  ShieldCheck,
  Sparkles,
  Music,
  Camera,
  ChevronLeft,
  Play,
  Pause,
  Shield,
  Zap,
  CheckCircle2,
  Lock,
  Radio
} from 'lucide-react';

export default function PhoneWidget() {
  const [deviceMode, setDeviceMode] = useState('phone'); // 'phone' | 'tablet'
  const [screenApp, setScreenApp] = useState('home'); // 'home' | 'comms' | 'passport' | 'quests' | 'spellforge' | 'music' | 'camera' | 'status'
  const [isPlaying, setIsPlaying] = useState(false);
  const [activeCommsContact, setActiveCommsContact] = useState('Dr. Maelis Voss');
  const [spellSelectedElement, setSpellSelectedElement] = useState(null);
  const [spellSelectedUtility, setSpellSelectedUtility] = useState(null);
  const [spellResult, setSpellResult] = useState('');

  const [npcMessages, setNpcMessages] = useState({
    'Dr. Maelis Voss': [
      { id: 1, text: 'Student, verify your Aethercore frequency before entry into Lab 4.', time: '09:12' },
      { id: 2, text: 'The Lightborn aura logic indicates a minor resonance shift in your record.', time: '09:15' },
    ],
    'Dean Cassian Rook': [
      { id: 3, text: 'Welcome to Cyacademy. Your provisional registration is active.', time: '08:30' },
      { id: 4, text: 'Remember to complete your daily Aura Passport check-in on the Bulletin Node.', time: '08:35' },
    ],
    'Agent Mara Quell': [
      { id: 5, text: 'DGA Field Alert: Patrol routes in Sector 7 are under heightened monitoring.', time: '09:00' },
      { id: 6, text: 'Keep your netrunner tools ready in case of PRISM corruption spikes.', time: '09:05' },
    ],
    'Archivist Selene': [
      { id: 7, text: 'Purge-era genealogy records have been logged in the restricted archives.', time: '08:45' },
    ],
  });
  const [chatInput, setChatInput] = useState('');

  const player = useOSStore((s) => s.gameplay.player);
  const addCredits = useOSStore((s) => s.addCredits);
  const addXP = useOSStore((s) => s.addXP);
  const purgePrismCorruption = useOSStore((s) => s.purgePrismCorruption);

  const handleSendNpcMessage = (e) => {
    if (e.key !== 'Enter' || !chatInput.trim()) return;
    setNpcMessages((prev) => ({
      ...prev,
      [activeCommsContact]: [
        ...(prev[activeCommsContact] || []),
        { id: Date.now(), text: chatInput.trim(), time: 'Just now', isPlayer: true },
      ],
    }));
    setChatInput('');
  };

  const handleSynthesizeSpell = () => {
    if (!spellSelectedElement || !spellSelectedUtility) {
      setSpellResult('⚠️ Select 1 Element & 1 Utility module.');
      return;
    }
    const spellName = `${spellSelectedElement} ${spellSelectedUtility}`;
    addCredits(75);
    addXP(40);
    purgePrismCorruption(1.5);
    setSpellResult(`✨ Synthesized [${spellName}]! +75 ₡, +40 XP, PRISM Corruption Reduced.`);
    setSpellSelectedElement(null);
    setSpellSelectedUtility(null);
  };

  return (
    <motion.div
      layout
      transition={{ type: 'spring', stiffness: 300, damping: 30 }}
      className={`relative select-none overflow-hidden transition-all duration-300 ${
        deviceMode === 'tablet'
          ? 'w-[540px] h-[480px] rounded-[36px] border-[10px] border-slate-900 bg-slate-950 shadow-[0_25px_70px_rgba(140,100,250,0.4)]'
          : 'w-[240px] h-[460px] rounded-[42px] border-[10px] border-[#1C1C1E] bg-[#1C1C1E] shadow-[0_25px_60px_rgba(0,0,0,0.5)]'
      }`}
    >
      {/* Top Bezel Header Controls */}
      <div className="absolute top-0 left-0 right-0 h-7 bg-[#1C1C1E] z-30 px-4 flex items-center justify-between text-white/80">
        <div className="flex items-center gap-1.5 text-[9px] font-mono font-bold text-cyan-300">
          <Radio size={12} className="animate-pulse" />
          <span>{deviceMode === 'tablet' ? 'CYCADEMY TABLET' : 'CYBER COMM'}</span>
        </div>

        {/* Morph Device Mode Toggle (Phone 📱 ↔ Tablet 📱✨) */}
        <button
          onClick={() => setDeviceMode((prev) => (prev === 'phone' ? 'tablet' : 'phone'))}
          className="flex items-center gap-1 rounded-full bg-white/10 hover:bg-white/20 px-2 py-0.5 text-[9px] font-bold text-amber-300 transition"
          title={deviceMode === 'phone' ? 'Expand to Cyber-Tablet' : 'Switch to Phone Mode'}
        >
          {deviceMode === 'phone' ? (
            <>
              <Tablet size={12} /> Expand ↔
            </>
          ) : (
            <>
              <Smartphone size={12} /> Phone Mode 📱
            </>
          )}
        </button>
      </div>

      {/* Screen Display Frame with Starry Cyber Wallpaper */}
      <div
        className="relative h-full w-full overflow-hidden bg-cover bg-center flex flex-col justify-between p-3 pt-8 text-white"
        style={{
          backgroundImage: `url('https://images.unsplash.com/photo-1506703719100-a0f3a48c0f86?q=80&w=600&auto=format&fit=crop')`,
        }}
      >
        {/* Dark Overlay Gradient */}
        <div className="absolute inset-0 bg-gradient-to-b from-black/60 via-black/30 to-black/80 pointer-events-none" />

        {/* Top Screen Status Bar */}
        <div className="relative z-10 flex justify-between items-center text-[10px] font-bold px-2 text-white/90">
          <span>09:41</span>
          <div className="flex gap-1.5 items-center font-mono text-[9px] text-cyan-300">
            <span>📶 AURELINE_5G</span>
            <span>🔋 100%</span>
          </div>
        </div>

        {/* ------------------------------------------------------------------ */}
        {/* SCREEN DISPLAY CONTENT (STRICTLY ON-DEVICE APPS)                   */}
        {/* ------------------------------------------------------------------ */}
        <div className="relative z-10 my-auto flex-1 flex flex-col justify-center w-full py-2 overflow-hidden">
          {/* HOME SCREEN APP GRID */}
          {screenApp === 'home' && (
            <div className="w-full space-y-3">
              {/* Player Identity Status Card */}
              <button
                onClick={() => setScreenApp('status')}
                className="w-full rounded-2xl bg-white/15 backdrop-blur-md border border-white/25 p-2 flex items-center justify-between hover:bg-white/25 transition shadow"
              >
                <div className="flex items-center gap-2">
                  <div className="w-7 h-7 rounded-full bg-purple-400/30 border border-purple-200 flex items-center justify-center font-bold text-xs">
                    P
                  </div>
                  <div className="text-left">
                    <div className="text-[10px] font-bold text-white leading-none">PLAYERNAME</div>
                    <div className="text-[9px] text-cyan-300">Level {player.level} • ₡{player.credits}</div>
                  </div>
                </div>
                <Shield size={14} className="text-emerald-400" />
              </button>

              {/* On-Device App Launcher Buttons (NO DESKTOP WINDOW TRIGGERS) */}
              <div className={`grid gap-2.5 ${deviceMode === 'tablet' ? 'grid-cols-6' : 'grid-cols-3'}`}>
                {/* Comms & Messenger */}
                <button
                  onClick={() => setScreenApp('comms')}
                  className="flex flex-col items-center group"
                >
                  <div className="h-11 w-11 rounded-2xl bg-gradient-to-br from-pink-400/80 to-purple-600/80 backdrop-blur-md border border-white/30 shadow flex items-center justify-center text-white group-hover:scale-105 transition">
                    <MessageSquare size={20} />
                  </div>
                  <span className="text-[9px] font-medium text-white/90 mt-1">Messenger</span>
                </button>

                {/* Aura Passport Mobile */}
                <button
                  onClick={() => setScreenApp('passport')}
                  className="flex flex-col items-center group"
                >
                  <div className="h-11 w-11 rounded-2xl bg-gradient-to-br from-cyan-400/80 to-blue-600/80 backdrop-blur-md border border-white/30 shadow flex items-center justify-center text-white group-hover:scale-105 transition">
                    <UserCheck size={20} />
                  </div>
                  <span className="text-[9px] font-medium text-white/90 mt-1">ID Passport</span>
                </button>

                {/* Quests & DGA Tasks */}
                <button
                  onClick={() => setScreenApp('quests')}
                  className="flex flex-col items-center group"
                >
                  <div className="h-11 w-11 rounded-2xl bg-gradient-to-br from-amber-400/80 to-orange-600/80 backdrop-blur-md border border-white/30 shadow flex items-center justify-center text-white group-hover:scale-105 transition">
                    <ShieldCheck size={20} />
                  </div>
                  <span className="text-[9px] font-medium text-white/90 mt-1">DGA Tasks</span>
                </button>

                {/* SpellForge Mobile */}
                <button
                  onClick={() => setScreenApp('spellforge')}
                  className="flex flex-col items-center group"
                >
                  <div className="h-11 w-11 rounded-2xl bg-gradient-to-br from-violet-400/80 to-fuchsia-600/80 backdrop-blur-md border border-white/30 shadow flex items-center justify-center text-white group-hover:scale-105 transition">
                    <Sparkles size={20} />
                  </div>
                  <span className="text-[9px] font-medium text-white/90 mt-1">SpellForge</span>
                </button>

                {/* Music Player */}
                <button
                  onClick={() => setScreenApp('music')}
                  className="flex flex-col items-center group"
                >
                  <div className="h-11 w-11 rounded-2xl bg-gradient-to-br from-emerald-400/80 to-teal-600/80 backdrop-blur-md border border-white/30 shadow flex items-center justify-center text-white group-hover:scale-105 transition">
                    <Music size={20} />
                  </div>
                  <span className="text-[9px] font-medium text-white/90 mt-1">Music</span>
                </button>

                {/* Camera Viewfinder */}
                <button
                  onClick={() => setScreenApp('camera')}
                  className="flex flex-col items-center group"
                >
                  <div className="h-11 w-11 rounded-2xl bg-gradient-to-br from-slate-400/80 to-slate-700/80 backdrop-blur-md border border-white/30 shadow flex items-center justify-center text-white group-hover:scale-105 transition">
                    <Camera size={20} />
                  </div>
                  <span className="text-[9px] font-medium text-white/90 mt-1">Camera</span>
                </button>
              </div>
            </div>
          )}

          {/* COMMS & MESSENGER APP */}
          {screenApp === 'comms' && (
            <div className="w-full h-full flex flex-col justify-between bg-black/85 backdrop-blur-md rounded-2xl p-3 border border-pink-400/30 text-xs">
              <div className="flex items-center justify-between border-b border-pink-400/30 pb-2">
                <button onClick={() => setScreenApp('home')} className="text-white/70 hover:text-white flex items-center gap-1">
                  <ChevronLeft size={14} /> Back
                </button>
                <span className="font-bold font-mono text-pink-300 text-[11px]">CYCADEMY MESSENGER</span>
                <MessageSquare size={14} className="text-pink-400" />
              </div>

              {/* Contact Selector */}
              <div className="flex gap-1 overflow-x-auto py-1 border-b border-white/10">
                {Object.keys(npcMessages).map((npc) => (
                  <button
                    key={npc}
                    onClick={() => setActiveCommsContact(npc)}
                    className={`px-2 py-0.5 rounded-full text-[9px] whitespace-nowrap transition ${
                      activeCommsContact === npc
                        ? 'bg-pink-500 text-white font-bold'
                        : 'bg-white/10 text-white/60 hover:bg-white/20'
                    }`}
                  >
                    {npc}
                  </button>
                ))}
              </div>

              {/* Chat Log */}
              <div className="flex-1 overflow-auto space-y-2 my-2 pr-1">
                {(npcMessages[activeCommsContact] || []).map((msg) => (
                  <div
                    key={msg.id}
                    className={`rounded-lg p-2 border space-y-0.5 ${
                      msg.isPlayer
                        ? 'bg-purple-900/40 border-purple-500/40 ml-4'
                        : 'bg-white/5 border-white/10 mr-4'
                    }`}
                  >
                    <div className="flex justify-between items-center text-[9px]">
                      <span className="font-bold text-cyan-300">{msg.isPlayer ? 'PLAYERNAME' : activeCommsContact}</span>
                      <span className="text-white/40">{msg.time}</span>
                    </div>
                    <div className="text-white/90 text-[10px]">{msg.text}</div>
                  </div>
                ))}
              </div>

              <input
                type="text"
                value={chatInput}
                onChange={(e) => setChatInput(e.target.value)}
                onKeyDown={handleSendNpcMessage}
                placeholder={`Message ${activeCommsContact}...`}
                className="w-full rounded-xl border border-pink-400/40 bg-black/60 px-3 py-1.5 text-xs text-white outline-none focus:border-pink-400 font-mono"
              />
            </div>
          )}

          {/* AURA PASSPORT MOBILE APP */}
          {screenApp === 'passport' && (
            <div className="w-full h-full flex flex-col justify-between bg-black/80 backdrop-blur-md rounded-2xl p-3 border border-cyan-400/30 text-xs">
              <div className="flex items-center justify-between border-b border-cyan-400/30 pb-2">
                <button onClick={() => setScreenApp('home')} className="text-white/70 hover:text-white flex items-center gap-1">
                  <ChevronLeft size={14} /> Back
                </button>
                <span className="font-bold font-mono text-cyan-300 text-[11px]">AURA PASSPORT BADGE</span>
                <UserCheck size={14} className="text-cyan-400" />
              </div>

              <div className="rounded-xl border border-cyan-400/40 bg-gradient-to-br from-purple-900/50 to-slate-900/80 p-3 space-y-2 text-[10px]">
                <div className="flex justify-between items-center border-b border-white/10 pb-1">
                  <span className="text-white/60">Student:</span>
                  <span className="font-bold text-white">PLAYERNAME</span>
                </div>
                <div className="flex justify-between items-center border-b border-white/10 pb-1">
                  <span className="text-white/60">Serial ID:</span>
                  <span className="font-mono text-cyan-300">CY-9021-X9</span>
                </div>
                <div className="flex justify-between items-center border-b border-white/10 pb-1">
                  <span className="text-white/60">Level / XP:</span>
                  <span className="font-bold text-emerald-400">Level {player.level} ({player.xp} XP)</span>
                </div>
                <div className="flex justify-between items-center border-b border-white/10 pb-1">
                  <span className="text-white/60">Balance:</span>
                  <span className="font-bold text-emerald-400">₡{player.credits} Credits</span>
                </div>
                <div className="flex justify-between items-center">
                  <span className="text-white/60">Aura Status:</span>
                  <span className="font-bold text-emerald-400 flex items-center gap-1">
                    <CheckCircle2 size={12} /> ACTIVE
                  </span>
                </div>
              </div>

              <div className="rounded-lg bg-white p-2 text-center font-mono text-[9px] text-black font-bold tracking-widest border border-cyan-300">
                ||| | |||| ||| |||| | ||||| CY-9021
              </div>
            </div>
          )}

          {/* QUESTS & DGA TASKS MOBILE APP */}
          {screenApp === 'quests' && (
            <div className="w-full h-full flex flex-col justify-between bg-black/80 backdrop-blur-md rounded-2xl p-3 border border-amber-400/30 text-xs">
              <div className="flex items-center justify-between border-b border-amber-400/30 pb-2">
                <button onClick={() => setScreenApp('home')} className="text-white/70 hover:text-white flex items-center gap-1">
                  <ChevronLeft size={14} /> Back
                </button>
                <span className="font-bold font-mono text-amber-300 text-[11px]">ACTIVE DGA TASKS</span>
                <ShieldCheck size={14} className="text-amber-400" />
              </div>

              <div className="space-y-2 my-2 overflow-auto text-[10px]">
                <div className="rounded-xl border border-amber-400/30 bg-white/5 p-2.5 space-y-1">
                  <div className="font-bold text-amber-300 flex items-center gap-1">
                    <Zap size={12} className="text-amber-400" /> Sector 7 Patrol Drill
                  </div>
                  <div className="text-white/80">Scan perimeter net nodes for X.A.N.A. specters.</div>
                  <div className="text-emerald-400 font-bold">Reward: +200 ₡, +100 XP</div>
                </div>

                <div className="rounded-xl border border-white/10 bg-white/5 p-2.5 space-y-1">
                  <div className="font-bold text-purple-300 flex items-center gap-1">
                    <Lock size={12} className="text-purple-400" /> Faith Medical Record Scan
                  </div>
                  <div className="text-white/80">Verify student aura health in medical archives.</div>
                  <div className="text-emerald-400 font-bold">Reward: +150 ₡, +75 XP</div>
                </div>
              </div>
            </div>
          )}

          {/* SPELLFORGE MOBILE SYNTHESIZER APP */}
          {screenApp === 'spellforge' && (
            <div className="w-full h-full flex flex-col justify-between bg-black/85 backdrop-blur-md rounded-2xl p-3 border border-violet-400/30 text-xs">
              <div className="flex items-center justify-between border-b border-violet-400/30 pb-2">
                <button onClick={() => setScreenApp('home')} className="text-white/70 hover:text-white flex items-center gap-1">
                  <ChevronLeft size={14} /> Back
                </button>
                <span className="font-bold font-mono text-violet-300 text-[11px]">SPELLFORGE MOBILE</span>
                <Sparkles size={14} className="text-violet-400" />
              </div>

              {/* Module Selectors */}
              <div className="space-y-2 my-2 text-[10px]">
                <div>
                  <div className="text-white/50 mb-1">Select Element:</div>
                  <div className="grid grid-cols-3 gap-1">
                    {['Firewall', 'Cryo', 'Encryption'].map((el) => (
                      <button
                        key={el}
                        onClick={() => setSpellSelectedElement(el)}
                        className={`p-1.5 rounded-lg border font-semibold transition ${
                          spellSelectedElement === el
                            ? 'border-violet-400 bg-violet-500/30 text-white'
                            : 'border-white/10 bg-white/5 text-white/70 hover:bg-white/10'
                        }`}
                      >
                        {el}
                      </button>
                    ))}
                  </div>
                </div>

                <div>
                  <div className="text-white/50 mb-1">Select Utility:</div>
                  <div className="grid grid-cols-3 gap-1">
                    {['Routing', 'Anchor', 'Pulse'].map((ut) => (
                      <button
                        key={ut}
                        onClick={() => setSpellSelectedUtility(ut)}
                        className={`p-1.5 rounded-lg border font-semibold transition ${
                          spellSelectedUtility === ut
                            ? 'border-cyan-400 bg-cyan-500/30 text-white'
                            : 'border-white/10 bg-white/5 text-white/70 hover:bg-white/10'
                        }`}
                      >
                        {ut}
                      </button>
                    ))}
                  </div>
                </div>

                {spellResult && (
                  <div className="rounded-lg bg-slate-900 border border-violet-400/40 p-2 text-violet-300 font-mono text-[9px] animate-fade-in">
                    {spellResult}
                  </div>
                )}
              </div>

              <button
                onClick={handleSynthesizeSpell}
                className="w-full rounded-xl border border-violet-400 bg-violet-500/20 py-2 font-bold font-mono text-violet-300 hover:bg-violet-500/40 transition shadow text-xs flex items-center justify-center gap-1.5"
              >
                <Sparkles size={14} className="text-violet-400" /> [ SYNTHESIZE SPELL ]
              </button>
            </div>
          )}

          {/* MUSIC PLAYER APP */}
          {screenApp === 'music' && (
            <div className="w-full space-y-3 bg-black/75 backdrop-blur-md rounded-2xl p-3 border border-white/20">
              <div className="flex items-center justify-between">
                <button onClick={() => setScreenApp('home')} className="text-white/70 hover:text-white">
                  <ChevronLeft size={16} />
                </button>
                <span className="text-[10px] font-bold text-cyan-300">Aether Synth Radio</span>
                <div className="w-4" />
              </div>

              <div className="w-20 h-20 mx-auto rounded-xl bg-purple-900/60 border border-purple-400/40 flex items-center justify-center text-purple-300">
                <Music size={32} className={isPlaying ? 'animate-bounce' : ''} />
              </div>

              <div className="text-center space-y-0.5">
                <div className="text-[11px] font-bold text-white">Aureline Sprawl Synth Track #04</div>
                <div className="text-[9px] text-white/60">Cyacademy Student Net Radio</div>
              </div>

              <button
                onClick={() => setIsPlaying((prev) => !prev)}
                className="w-10 h-10 mx-auto rounded-full bg-cyan-400 text-slate-950 flex items-center justify-center font-bold hover:scale-105 transition shadow"
              >
                {isPlaying ? <Pause size={18} /> : <Play size={18} className="ml-0.5" />}
              </button>
            </div>
          )}

          {/* CAMERA VIEWFINDER APP */}
          {screenApp === 'camera' && (
            <div className="w-full space-y-2 bg-black/80 backdrop-blur-md rounded-2xl p-3 border border-white/20 text-center">
              <div className="flex items-center justify-between">
                <button onClick={() => setScreenApp('home')} className="text-white/70 hover:text-white">
                  <ChevronLeft size={16} />
                </button>
                <span className="text-[10px] font-bold text-pink-400">Cyber Viewfinder</span>
                <div className="w-4" />
              </div>

              <div className="relative w-full h-28 rounded-xl border border-dashed border-cyan-400/60 bg-black/40 overflow-hidden flex items-center justify-center">
                <div className="absolute inset-2 border border-cyan-400/30 rounded-lg pointer-events-none" />
                <span className="text-[10px] text-cyan-300 font-mono">AURA LENS: ACTIVE</span>
              </div>

              <button
                onClick={() => alert('📷 Snapshot captured to Files archive!')}
                className="w-8 h-8 mx-auto rounded-full border-2 border-white bg-white/30 hover:bg-white/50 transition shadow"
              />
            </div>
          )}

          {/* STATUS VIEW APP */}
          {screenApp === 'status' && (
            <div className="w-full space-y-2 bg-black/75 backdrop-blur-md rounded-2xl p-3 border border-white/20 text-xs">
              <div className="flex items-center justify-between border-b border-white/10 pb-1">
                <button onClick={() => setScreenApp('home')} className="text-white/70 hover:text-white">
                  <ChevronLeft size={16} />
                </button>
                <span className="text-[10px] font-bold text-amber-300">Identity Status</span>
                <div className="w-4" />
              </div>

              <div className="space-y-1.5 text-[10px]">
                <div className="flex justify-between">
                  <span className="text-white/60">Level:</span>
                  <span className="font-bold text-emerald-400">Level {player.level}</span>
                </div>
                <div className="flex justify-between">
                  <span className="text-white/60">XP Progress:</span>
                  <span className="font-bold text-cyan-300">{player.xp} XP</span>
                </div>
                <div className="flex justify-between">
                  <span className="text-white/60">Credits:</span>
                  <span className="font-bold text-emerald-400">₡{player.credits}</span>
                </div>
                <div className="flex justify-between">
                  <span className="text-white/60">Aura Health:</span>
                  <span className="font-bold text-purple-400">{player.auraHealth}%</span>
                </div>
              </div>
            </div>
          )}
        </div>

        {/* Home Bar Indicator */}
        <div className="relative z-10 flex justify-center pb-1">
          <button
            onClick={() => setScreenApp('home')}
            className="h-1.5 w-20 bg-white/70 rounded-full hover:bg-white transition cursor-pointer"
            title="Return to Home Screen"
          />
        </div>
      </div>
    </motion.div>
  );
}
